// Native Qt desktop UI regression with explicitly synthetic mathematical fixtures.
// The full application worker/engine acceptance is tested separately.
#include "graphworkbench.h"
#include "desktopworkbench.h"
#include "workbenchpalette.h"
#include <QtTest/QTest>
#include <QApplication>
#include <QClipboard>
#include <QDir>
#include <QJsonArray>
#include <QXmlStreamReader>
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace EmciGraph;
namespace {
int checks=0;void check(bool value,const char *message){++checks;if(!value)throw std::runtime_error(message);}
void settle(){QApplication::processEvents();QCoreApplication::sendPostedEvents(nullptr,QEvent::LayoutRequest);QApplication::processEvents();}
void reveal(QWidget *w){for(auto *p=w->parentWidget();p;p=p->parentWidget())if(auto *s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(w,8,8);settle();}
ScalarResult evaluator(const QString&e,const QMap<QString,double>&v,int){const double x=v.value("x"),y=v.value("y"),t=v.value("t");double z=0;bool recognized=true;
 if(e=="x^2")z=x*x;else if(e=="1/x")z=1/x;else if(e=="x^2+y^2")z=x*x+y*y;else if(e=="x^2+y^2-4")z=x*x+y*y-4;else if(e=="cos(t)")z=std::cos(t);else if(e=="sin(t)")z=std::sin(t);else if(e=="2")z=2;else z=e.toDouble(&recognized);
 return {recognized&&std::isfinite(z),z,recognized?QString():QString("Unknown test fixture")};}
Series fixture(const char *name,Kind kind,const char *expression){Series s;s.id=name;s.name=name;s.kind=kind;s.expression=expression;return s;}
}
int main(int argc,char **argv){QApplication app(argc,argv);try{
 const QString out=argc>1?QString::fromLocal8Bit(argv[1]):QString();if(!out.isEmpty())QDir().mkpath(out);
 GraphWorkbench w;Request pending;std::shared_ptr<std::atomic_bool>cancel;w.onSampleRequested=[&](Request r,std::shared_ptr<std::atomic_bool>c){pending=r;cancel=c;};
 w.resize(900,650);w.show();w.activateWindow();settle();auto *tabs=w.findChild<QTabWidget*>("graphTabs");auto *entry=w.findChild<QPushButton*>("graphAddCurve");auto *expression=w.findChild<QLineEdit*>("graphExpression");auto *plot=w.findChild<QPushButton*>("graphPlot");auto *canvas=w.findChild<QWidget*>("graphCanvas");
 check(tabs&&entry&&expression&&plot&&canvas,"native graph controls exist");check(w.saveState().value("series").toArray().isEmpty(),"fresh plot has no sample calculation");
 QTest::mouseClick(entry,Qt::LeftButton);settle();check(expression->isEnabled()&&expression->hasFocus(),"mouse Add curve focuses native expression field");QTest::keyClicks(expression,"x^2");check(w.saveState().value("series").toArray()[0].toObject().value("expression")=="x^2","keyboard updates stored expression");
 expression->selectAll();QApplication::clipboard()->setText("1/x");QTest::keyClick(expression,Qt::Key_V,Qt::ControlModifier);check(expression->text()=="1/x","native Ctrl+V works");QTest::keyClick(expression,Qt::Key_Z,Qt::ControlModifier);check(expression->text()=="x^2","native Undo restores input");
 QTest::mouseClick(plot,Qt::LeftButton);auto stale=sample(pending,evaluator,cancel);w.cancelWork();w.acceptResult(stale);check(w.result().series.isEmpty(),"cancelled stale result rejected");
 auto complete=[&]{w.requestPlot();w.acceptResult(sample(pending,evaluator,cancel));settle();};complete();check(w.result().series.size()==1&&!w.result().series[0].paths.isEmpty(),"native plot accepts sampled curve");
 const auto squareState=w.saveState();if(!out.isEmpty())w.grab().save(out+"/native-curve-synthetic-fixture.png");
 QImage png=QImage::fromData(w.exportBytes("png"),"PNG");check(!png.isNull(),"PNG export decodes");QXmlStreamReader svg(w.exportBytes("svg"));while(!svg.atEnd())svg.readNext();check(!svg.hasError(),"2D SVG export is valid XML");
 auto *grid=w.findChild<QCheckBox*>();Q_UNUSED(grid);
 auto configure=[&](QVector<Series> series,bool surface=false){Request r;r.series=series;r.bounds={-3,3,-3,3};auto state=saveRequest(r);state.insert("view3d",surface);check(w.restoreState(state),"fixture state restores without evaluation");check(w.result().series.isEmpty(),"restore is parse-only");complete();tabs->setCurrentIndex(0);settle();};
 auto polar=fixture("Polar circle",Kind::Polar,"2");auto param=fixture("Parametric circle",Kind::Parametric,"cos(t)");param.expressionY="sin(t)";param.color=QColor("#bd653b");auto implicit=fixture("Implicit circle",Kind::Implicit,"x^2+y^2-4");implicit.color=QColor("#38996a");configure({polar,param,implicit});
 check(w.result().series.size()==3,"polar parametric implicit series sampled together");for(const auto&s:w.result().series)check(!s.paths.isEmpty(),"all three curve kinds have geometry");if(!out.isEmpty())w.grab().save(out+"/native-multikind-synthetic-fixture.png");
 configure({fixture("Reciprocal pole",Kind::Explicit,"1/x")});for(const auto &path:w.result().series[0].paths)for(int i=1;i<path.size();++i)check(!(path[i-1].x()<0&&path[i].x()>0),"reciprocal path never joins across zero pole");
 QVector<Series> twenty;for(int i=0;i<20;++i){auto s=fixture(qPrintable(QString("series-%1").arg(i)),Kind::Explicit,qPrintable(QString::number(i/5.)));s.color=QColor::fromHsv(i*18,190,180);twenty<<s;}configure(twenty);check(w.result().series.size()==20,"twenty independently enabled series render");auto full=w.saveState();w.addExpression("999");check(w.saveState()==full,"twenty-first series cannot overwrite existing data");twenty[7].enabled=false;configure(twenty);check(w.result().series.size()==19,"disabled series excluded while its configuration remains");check(w.saveState().value("series").toArray().size()==20,"visibility toggle preserves twenty configurations");
 check(w.restoreState(squareState),"restore square table fixture");complete();tabs->setCurrentIndex(3);settle();auto *generate=w.findChild<QPushButton*>("graphGenerateTable");reveal(generate);QTest::mouseClick(generate,Qt::LeftButton);w.acceptResult(sample(pending,evaluator,cancel));settle();auto *table=w.findChild<QTableWidget*>("graphSampleTable");check(table&&table->rowCount()==21,"table has requested range rows");reveal(table);table->scrollToTop();table->setCurrentCell(0,0);table->editItem(table->item(0,0));settle();auto *cell=table->findChild<QLineEdit*>();check(cell&&cell->isVisible(),"table cell uses native editable field");cell->selectAll();QTest::keyClicks(cell,"0.25");QTest::keyClick(cell,Qt::Key_Return);settle();check(pending.tableInputs.size()==21&&pending.tableInputs[0]==.25,"edited abscissa resamples requested rows");w.acceptResult(sample(pending,evaluator,cancel));check(std::abs(w.result().table[0].y-.0625)<1e-12,"edited table value correct");check(w.exportBytes("csv").count('\n')==22,"CSV exports all table rows and header");const auto canonicalCsv=w.exportBytes("csv");const auto presentationState=w.saveState();w.setNumberPresentation(1,',');check(w.displayNumber(8000000.25,12).replace(QChar(0x202f),' ')=="8 000 000,25","graph display follows grouping and decimal comma");check(w.saveState()==presentationState&&w.exportBytes("csv")==canonicalCsv,"graph formatting preserves request and canonical CSV without sampling");check(table->item(0,0)->text()=="0,25"&&table->item(0,2)->text()=="0,0625","displayed table follows number preferences");table->item(0,0)->setText("0,5");check(pending.tableInputs[0]==.5,"localized decimal comma table edit parses correctly");w.acceptResult(sample(pending,evaluator,cancel));w.setNumberPresentation(0,'.');if(!out.isEmpty())w.grab().save(out+"/native-table-synthetic-fixture.png");
 configure({fixture("Surface",Kind::Surface3D,"x^2+y^2")},true);check(!w.result().series[0].triangles.isEmpty(),"surface contains three-dimensional triangles");QImage before=canvas->grab().toImage();auto oldState=w.saveState();QTest::mousePress(canvas,Qt::LeftButton,Qt::NoModifier,canvas->rect().center());QTest::mouseMove(canvas,canvas->rect().center()+QPoint(45,25),30);QTest::mouseRelease(canvas,Qt::LeftButton,Qt::NoModifier,canvas->rect().center()+QPoint(45,25));settle();check(w.saveState().value("yaw")!=oldState.value("yaw")&&canvas->grab().toImage()!=before,"mouse drag changes camera and rendered surface pixels");before=canvas->grab().toImage();QTest::keyClick(canvas,Qt::Key_Right);settle();check(canvas->grab().toImage()!=before,"keyboard rotation changes surface pixels");oldState=w.saveState();QTest::keyClick(canvas,Qt::Key_Plus);settle();check(w.saveState().value("zoom3d")!=oldState.value("zoom3d"),"keyboard zoom changes3D camera");check(!QImage::fromData(w.exportBytes("png")).isNull()&&w.exportBytes("svg").isEmpty(),"surface PNG exports and unsupported3D SVG stays unavailable");if(!out.isEmpty())w.grab().save(out+"/native-3d-synthetic-fixture.png");
 Request narrow;narrow.series={fixture("Narrow offset",Kind::Explicit,"2")};narrow.bounds={1e12-.000244140625,1e12,-1,1};check(w.restoreState(saveRequest(narrow)),"narrow large-offset view is valid");tabs->setCurrentIndex(0);settle();check(!w.grab().isNull(),"large-offset sub-ULP grid spacing paints without a stalled floating loop");
 for(const auto size:{QSize(320,540),QSize(680,540),QSize(1200,540),QSize(420,900)}){w.resize(size);for(int i=0;i<4;++i){tabs->setCurrentIndex(i);settle();check(w.size()==size,"each graph page fits narrow wide tall desktop viewport");
 bool fits=true;for(auto *scroll:w.findChildren<QScrollArea*>())if(scroll->isVisibleTo(&w)){const bool fit=scroll->horizontalScrollBar()->maximum()==0&&scroll->widget()->width()<=scroll->viewport()->width();if(!fit)std::cerr<<"SCROLL GEOMETRY tab="<<i<<" width="<<size.width()<<" viewport="<<scroll->viewport()->width()<<" body="<<scroll->widget()->width()<<" maximum="<<scroll->horizontalScrollBar()->maximum()<<'\n';fits&=fit;}
 for(auto *button:w.findChildren<QAbstractButton*>())if(button->isVisibleTo(&w)){const QRect bounds(button->mapTo(&w,QPoint()),button->size());const bool fit=bounds.left()>=0&&bounds.right()<w.width();if(!fit)std::cerr<<"BUTTON GEOMETRY tab="<<i<<" width="<<size.width()<<" name="<<button->objectName().toStdString()<<" caption="<<button->text().toStdString()<<" x="<<bounds.x()<<" width="<<bounds.width()<<'\n';fits&=fit;}
 check(fits,"shown graph tab controls and local scroll content fit viewport width");}}
 std::cout<<checks<<" native desktop graph UI checks passed; synthetic sampler fixtures, no engine execution claim.\n";return 0;
 }catch(const std::exception&e){std::cerr<<"FAIL after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
